examples:
// Give all prim contents to anyone touching this object,
// But don't give this script itself.
default
{
touch_start
(
integer
num_detected
)
{
list
InventoryList
;
integer
count
=
llGetInventoryNumber
(
INVENTORY_ALL
);
// Count of all items in prim's contents
string
ItemName
;
while
(
count
--
)
{
ItemName
=
llGetInventoryName
(
INVENTORY_ALL
,
count
);
if
(
ItemName
!=
llGetScriptName
()
)
InventoryList
+=
ItemName
;
// add all contents except this script, to a list
}
// Give all the items to the toucher, in a folder named as per this prim's name
llGiveInventoryList
(
llDetectedKey
(
0
),
llGetObjectName
(),
InventoryList
);
}
}
